mapper.select:
select
    mn.*
from Sys_Download_Log mn

    
        and mn.Dl_Uid=#{params.dlUid}
    
    
        and INSTR(mn.Dl_Uname,#{params.dlUname})
    
    
        and INSTR(mn.Dl_File_Name,#{params.dlFileName})
    
    
        and mn.Dl_Time>#{params.dllTimeStart}
    
    
        and mn.Dl_Time<#{params.dlTimeEnd}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Dl_Time desc

select
mn.*,
sf.file_relation_id as fileRelationId
from Sys_Download_Log mn
left join sys_file sf on mn.Dl_Form_Id=sf.FileId
left join design_results_issued dri on dri.id=mn.Dl_Form_Id
left join pre_project pro on pro.P_Id=dri.P_Id

    
        and mn.Dl_Uid=#{params.dlUid}
    
    
        and INSTR(mn.Dl_Uname,#{params.dlUname})
    
    
        and INSTR(mn.Dl_File_Name,#{params.dlFileName})
    
    
        and mn.Dl_Time>#{params.dllTimeStart}
    
    
        and mn.Dl_Time<#{params.dlTimeEnd}
    
    
        and INSTR(pro.pName,#{params.pName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Dl_Time desc
